// Generated from the owned Whale UI component registry by scripts/prepare-whale-ui.mjs.
export const OPENUI_GUIDE = "## Interactive answers with Whale UI\n\nUse a whale-ui fence for a working page when interaction helps, or render_ui for a self-contained tool card. Pass program as language text or spec as a declarative object, never both. Ordinary prose and tool calls remain available outside the fence. Local operations do not require another model message.\n\nUse Whale UI for a useful interactive answer. Put its program in a whale-ui Markdown fence and start with root = Col(...). Every fence owns its local state. Only @ToAssistant or a button without a local action sends a new request to this same conversation.\n\n## Syntax Rules\n\n1. Each statement is on its own line: `identifier = Expression`\n2. `root` is the entry point — every program must define `root = Col(...)`\n3. Expressions are: strings (\"...\"), numbers, booleans (true/false), null, arrays ([...]), objects ({...}), or component calls TypeName(arg1, arg2, ...)\n4. Use references for readability: define `name = ...` on one line, then use `name` later\n5. EVERY variable (except root) MUST be referenced by at least one other variable. Unreferenced variables are silently dropped and will NOT render. Always include defined variables in their parent's children/items array.\n6. Arguments are POSITIONAL (order matters, not names). Write `SomeComp([children], \"row\", \"l\")` NOT `SomeComp([children], direction: \"row\", gap: \"l\")` — colon syntax is NOT supported and silently breaks\n7. Optional arguments can be omitted from the end\n8. Declare mutable state with `$varName = defaultValue`. Components marked with `$binding` can read/write these. Undeclared $variables are auto-created with null default.\n9. String concatenation: `\"text\" + $var + \"more\"`\n10. Dot member access: `query.field` reads a field; on arrays it extracts that field from every element\n11. Index access: `arr[0]`, `data[index]`\n12. Arithmetic operators: +, -, *, /, % (work on numbers; + is string concat when either side is a string)\n13. Comparison: ==, !=, >, <, >=, <=\n14. Logical: &&, ||, ! (prefix)\n15. Ternary: `condition ? valueIfTrue : valueIfFalse`\n16. Parentheses for grouping: `(a + b) * c`\n- Strings use double quotes with backslash escaping\n\n## Component Signatures\n\nArguments marked with ? are optional. Sub-components can be inline or referenced; prefer references for better streaming.\nProps typed `ActionExpression` accept one @step, or Action([@steps...]) for several. See the Action section for available steps (@ToAssistant, @OpenUrl, @Set, @Reset, @CopyToClipboard).\nProps marked `$binding<type>` accept a `$variable` reference for two-way binding.\n\n### Layout\nCol(children: any[], gap?: number, align?: \"start\" | \"center\" | \"end\" | \"stretch\") — Vertical layout; gap and padding units are 4px. Default gap follows article spacing.\nRow(children: any[], gap?: number, align?: \"start\" | \"center\" | \"end\" | \"stretch\", justify?: \"start\" | \"center\" | \"end\" | \"between\", wrap?: boolean) — Horizontal layout with vertically centered children.\nBox(children?: any[], direction?: \"row\" | \"col\", gap?: number, padding?: number, background?: string, radius?: \"sm\" | \"md\" | \"lg\" | \"xl\" | \"full\" | number, border?: boolean, width?: number | string, height?: number | string, flex?: number, align?: \"start\" | \"center\" | \"end\" | \"stretch\", justify?: \"start\" | \"center\" | \"end\" | \"between\", wrap?: boolean) — Flexible container. gap and padding use 4px units: padding 3 = 12px, 4 = 16px, 5 = 20px; width and height use pixels/CSS lengths. Named backgrounds use soft theme tints.\nGrid(children: any[], columns?: number, minChildWidth?: number, gap?: number) — Equal columns; use minChildWidth 240–280 for readable responsive fields and cards.\nCard(children: any[], variant?: \"outline\" | \"soft\", padding?: number, gap?: number) — Theme-aligned panel. padding and gap are 4px units, not pixels: padding 4 = 16px, padding 5 = 20px (default), gap 3 = 12px. Use a plain section for metrics; do not put each number in a separate card.\nCarousel(children: any[], itemWidth?: number, gap?: number) — Horizontal, scrollable list with snap-aligned items.\nPopover(trigger: string | any[], content: string | any[]) — Click to show a small details panel; Escape or outside click closes it.\nDivider() — A subtle horizontal separator.\nSpacer() — Fill remaining space in a row.\nGap and padding use 4px steps. Length is px or a CSS length. Radius is sm/md/lg/xl/full or px. Named colors follow the host theme; status backgrounds use soft tints.\n\n### Text\nTitle(text: string, size?: \"sm\" | \"md\" | \"lg\" | \"xl\" | \"2xl\" | \"3xl\", color?: string) — Page or section heading. Use md for the single page title, sm for a section; 2xl/3xl only for a key numeric value.\nText(text: string | any[], size?: \"xs\" | \"sm\" | \"md\" | \"lg\", color?: string, weight?: \"normal\" | \"medium\" | \"semibold\", italic?: boolean, lineThrough?: boolean, tabularNums?: boolean, maxLines?: number) — Paragraph with inline bold, italic, code and links; mixed arrays may contain components.\nCaption(text: string, color?: string) — Secondary small text.\nLabel(text: string) — A field or group label.\nBadge(text: string, color?: \"neutral\" | \"info\" | \"success\" | \"warning\" | \"danger\" | \"purple\" | \"pink\", icon?: string) — Compact theme-colored tag with optional Lucide icon.\nLink(text: string, url: string) — Open an HTTP(S) web URL.\nList(items: (string | ListItem)[], marker?: \"bullet\" | \"number\" | \"none\", timeline?: boolean) — A bullet, numbered or unmarked list; timeline connects item markers.\nListItem(title: string, description?: string, marker?: string, children?: any[]) — A list item with optional description, custom marker and child content.\nMarkdown(text: string) — Safe Markdown prose including headings, lists, quotes, fenced code and tables.\nQuote(text: string, cite?: string) — Quotation with a source attribution.\nCode(code: string, language?: string) — Code block with a host-backed copy button.\nMath(tex: string, inline?: boolean) — KaTeX formula; inline formulas sit within text.\n\n### Inputs\nButton(label: string, action?: ActionExpression, variant?: \"solid\" | \"outline\" | \"soft\" | \"ghost\", color?: \"primary\" | \"danger\" | \"success\", size?: \"sm\" | \"md\" | \"lg\", icon?: string, disabled?: boolean, block?: boolean) — Run local or host action steps; without an action, send the button label to the assistant.\nIconButton(icon: string, action?: ActionExpression, label?: string, variant?: \"outline\" | \"ghost\" | \"solid\") — Accessible round icon action.\nPressable(children: any[], action?: ActionExpression, selected?: boolean, padding?: number, background?: string, radius?: \"sm\" | \"md\" | \"lg\" | \"xl\" | \"full\" | number) — Keyboard-accessible clickable content with optional selected state.\nInput(value: $binding<string | number>, label?: string, type?: \"text\" | \"number\", placeholder?: string) — Bound text or numeric field; numeric edits store numbers, and an empty number stores null.\nTextArea(value: $binding<string>, label?: string, placeholder?: string, rows?: number) — Bound multiline text.\nSelect(value: $binding<string>, options: (string | {value: string, label: string})[], label?: string, placeholder?: string) — Bound dropdown with text or value/label options.\nSegmentedControl(value: $binding<string>, options: (string | {value: string, label: string})[], block?: boolean) — A bound single selection shown as adjacent buttons with arrow-key navigation.\nSlider(value: $binding<number>, min: number, max: number, step?: number, label?: string, unit?: string, marks?: {value: number, label: string}[]) — Bound numeric slider with label, unit and optional tick marks.\nCheckbox(checked: $binding<boolean>, label: string, lineThrough?: boolean) — Bound checkbox; optionally strike completed text.\nRadioGroup(value: $binding<string>, options: (string | {value: string, label: string, description?: string})[], label?: string, variant?: \"list\" | \"pills\" | \"cards\") — Bound radio choices as a list, pills or descriptive cards.\nDatePicker(value: $binding<string>, label?: string, min?: string, max?: string) — Bound local calendar date in YYYY-MM-DD format.\nTimer(seconds: $binding<number>, label?: string) — Durable countdown with start, pause and reset; updates bound seconds down to zero.\nForm(children: any[]) — Group all bound and plain member fields for assistant submission.\nDeclare mutable values as $variables with literal defaults. Bind the first input argument to a $variable. A Form submits all its bound and plain member fields.\n\n### Media and data\nSearchImage(query: string, aspectRatio?: number, radius?: \"sm\" | \"md\" | \"lg\" | \"xl\" | \"full\" | number, fit?: \"cover\" | \"contain\") — Find a real image through the host image-search resource. Failed requests can be retried.\nImage(src: string, alt: string, aspectRatio?: number, radius?: \"sm\" | \"md\" | \"lg\" | \"xl\" | \"full\" | number, fit?: \"cover\" | \"contain\") — Image from a URL; find an image for alt text if loading fails.\nIcon(name: string, size?: \"sm\" | \"md\" | \"lg\" | \"xl\", color?: string) — Lucide icon by kebab-case name.\nTable(columns: string[], rows: any[][]) — Scrollable data table with numeric alignment and support for components in cells.\nChart(type: \"bar\" | \"line\" | \"area\" | \"pie\" | \"donut\" | \"scatter\", data: Record<string, string | number>[], x?: string, series?: string[], format?: \"number\" | \"currency\" | \"percent\", currency?: string, stacked?: boolean, height?: number) — Accessible SVG chart with interactive series legend; supports bar, line, area, pie, donut and numeric scatter. Percent values use 45 for 45%.\nMap(markers: MapMarker[], route?: boolean, selected?: $binding<string>, height?: number) — MapLibre street map fitted to markers. Optional street route follows marker order; clicking a marker updates the selected binding.\nMapMarker(label: string, lat: number, lng: number, category?: string, icon?: string) — Map location with label, latitude, longitude and optional category/emoji.\nYouTube(video: string, title?: string) — YouTube video by known id or URL, embedded through privacy-enhanced mode.\n\n### Play\nFlashcard(front: string | any[], back: string | any[], hint?: string) — Tap to reveal a flashcard answer; flipped state persists across remounts.\nCelebration(when: boolean) — Brief confetti when the condition becomes true; respects reduced motion.\n\n### Drawing\nSvg(children: any[], viewBox: string, width?: number | string, height?: number | string) — Responsive SVG drawing; coordinates use the declared viewBox.\nG(children: any[], transform?: string, opacity?: number) — SVG group with transform and opacity.\nCircle(cx: number, cy: number, r: number, fill?: string, stroke?: string, strokeWidth?: number, opacity?: number) — SVG circle.\nEllipse(cx: number, cy: number, rx: number, ry: number, fill?: string, stroke?: string, strokeWidth?: number, opacity?: number) — SVG ellipse.\nRect(x: number, y: number, width: number, height: number, fill?: string, stroke?: string, strokeWidth?: number, opacity?: number, rx?: number) — SVG rectangle with optional corner rounding.\nLine(x1: number, y1: number, x2: number, y2: number, stroke?: string, strokeWidth?: number, opacity?: number) — SVG line.\nPath(d: string, fill?: string, stroke?: string, strokeWidth?: number, opacity?: number) — SVG path using standard path commands.\nPolyline(points: string, stroke?: string, strokeWidth?: number, fill?: string, opacity?: number) — SVG polyline using x,y coordinate pairs.\nPolygon(points: string, fill?: string, stroke?: string, strokeWidth?: number, opacity?: number) — Closed SVG polygon using x,y coordinate pairs.\nSvgText(text: string, x: number, y: number, size?: number, fill?: string, anchor?: \"start\" | \"middle\" | \"end\", weight?: \"normal\" | \"medium\" | \"semibold\") — SVG text anchored at coordinates.\nHtmlView(html: string, height?: number, title?: string) — Sandboxed HTML with inline scripts and approved script CDNs. Theme updates preserve iframe state; content height adapts unless fixed.\n\n### Other\nGenui(spec: Record<string, any>) — Render an existing declarative GenUI specification with the shared Whale UI state and action host.\nPlot(options: Record<string, any>) — Mathematical function plot. Pass the options object from the plot component schema.\nMermaid(options: Record<string, any>) — Mermaid diagram. Pass the options object from the mermaid component schema.\nScene3D(options: Record<string, any>) — Interactive three-dimensional scene. Pass the options object from the scene3d component schema.\nEChart(options: Record<string, any>) — ECharts data visualization. Pass the options object from the echart component schema.\nDiagram(options: Record<string, any>) — Structured diagram with nodes and edges. Pass the options object from the diagram component schema.\nBlocks(options: Record<string, any>) — Structured block drawing. Pass the options object from the blocks component schema.\nQuiz(options: Record<string, any>) — Locally graded quiz. Pass the options object from the quiz component schema.\nFileTree(options: Record<string, any>) — Expandable file tree. Pass the options object from the file-tree component schema.\nTimeline(options: Record<string, any>) — Chronological event list. Pass the options object from the timeline component schema.\nSteps(options: Record<string, any>) — Step sequence. Pass the options object from the steps component schema.\nKeyValue(options: Record<string, any>) — Key and value records. Pass the options object from the keyvalue component schema.\nDiff(options: Record<string, any>) — Source text differences. Pass the options object from the diff component schema.\nJson(options: Record<string, any>) — Expandable JSON data. Pass the options object from the json component schema.\nTabs(options: Record<string, any>) — Named tab panels. Pass the options object from the tabs component schema.\nAccordion(options: Record<string, any>) — Expandable sections. Pass the options object from the accordion component schema.\n\n## Built-in Functions\n\nData functions prefixed with `@` to distinguish from components. These are the ONLY functions available — do NOT invent new ones.\nUse @-prefixed built-in functions (@Count, @Sum, @Avg, @Min, @Max, @Round) on data. Do NOT hardcode computed values.\n\n@Count(array: any[]) → number — Returns array length\n@First(array: any[]) → any — Returns first element of array\n@Last(array: any[]) → any — Returns last element of array\n@Sum(numbers: number[]) → number — Sum of numeric array\n@Avg(numbers: number[]) → number — Average of numeric array\n@Min(numbers: number[]) → number — Minimum value in array\n@Max(numbers: number[]) → number — Maximum value in array\n@Sort(array: any[], field: string, direction?: \"asc\" | \"desc\") → any[] — Sort array by field. Direction: \"asc\" (default) or \"desc\"\n@Filter(array: any[], field: string, operator: \"==\" | \"!=\" | \">\" | \"<\" | \">=\" | \"<=\" | \"contains\", value: any) → any[] — Filter array by field value\n@Round(number: number, decimals?: number) → number — Round to N decimal places (default 0)\n@Abs(number: number) → number — Absolute value\n@Floor(number: number) → number — Round down to nearest integer\n@Ceil(number: number) → number — Round up to nearest integer\n@Each(array: any[], varName: string, template: any) — Evaluate template for each element. varName is the loop variable — use it ONLY inside the template expression (inline). Do NOT create a separate statement for the template.\n@Append(list: any[], item: any) → any[] — Copy the list with an item appended.\n@Prepend(list: any[], item: any) → any[] — Copy the list with an item prepended.\n@Concat(list: any[], more: any[]) → any[] — Combine two lists without changing either.\n@Remove(list: any[], field: string, value: any) → any[] — Remove matching field values; an empty field compares the item itself.\n@RemoveAt(list: any[], index: number) → any[] — Remove an item by index; negative indices start at the end.\n@Update(list: any[], field: string, value: any, setField: string, setValue: any) → any[] — Copy matching records with setField replaced by setValue.\n@Toggle(list: any[], item: any) → any[] — Add an absent item or remove its occurrences.\n@Includes(list: any[] | string, item: any) → boolean — Test membership in a list or substring membership in text.\n@Find(list: any[], field: string, value: any) → any — First record matching a field, or null.\n@IndexOf(list: any[], item: any) → number — Index of an item, or -1.\n@Take(list: any[], n: number) → any[] — First n items, or last abs(n) items for a negative count.\n@Slice(list: any[] | string, start: number, end?: number) → any[] | string — Slice from start up to end; negative indices count from the end.\n@Unique(list: any[]) → any[] — Distinct items in first-seen order.\n@Reverse(list: any[]) → any[] — A reversed copy.\n@Range(start: number, end: number, step?: number) → number[] — Numbers starting at start and stopping before end, with nonzero step (default 1).\n@Pick(list: any[]) → any — Random item, or null for an empty list. Use inside @Set to draw once.\n@Shuffle(list: any[]) → any[] — Randomly shuffled copy. Use inside @Set to shuffle once.\n@Flatten(list: any[]) → any[] — Flatten one level of nested lists.\n@Chunk(list: any[], size: number) → any[][] — Split into consecutive groups of positive size.\n@Pow(base: number, exponent: number) → number — Base raised to exponent.\n@Sqrt(number: number) → number — Square root, or null for a negative input.\n@Random(min: number, max: number, integer?: boolean) → number — Random value from min to max; integer mode includes both bounds. Use inside @Set.\n@Clamp(number: number, min: number, max: number) → number — Keep a number within the inclusive bounds.\n@Percent(part: number, total: number) → number — Part / total × 100; zero when total is zero.\n@Lerp(a: number, b: number, t: number) → number — Linear interpolation from a to b at fraction t.\n@Allocate(total: number, weights: number[], decimals?: number) → number[] — Distribute total in proportion to nonnegative weights, rounding shares to sum exactly to the rounded total.\n@Payment(principal: number, rate: number, periods: number) → number — Repayment per period using a rate in percent per period.\n@Convert(value: number, from: string, to: string) → number — Convert mm cm m km in ft yd mi; mg g kg oz lb st; ml l tsp tbsp floz cup pt qt gal (US); m/s km/h mph kn; m2 km2 ft2 ha acre; c f k.\n@Format(value: number, kind?: \"number\" | \"currency\" | \"percent\" | \"compact\", decimals?: number, currency?: string) → string — Locale-aware number, currency, percent (45 means 45%), or compact number formatting.\n@Join(list: any[], sep?: string, field?: string) → string — Join items or a chosen field, skipping null values. Default separator is comma and space.\n@Plural(n: number, word: string, plural?: string) → string — Count and singular/plural word. Default plural appends s.\n@Pad(value: string | number, length: number, char?: string) → string — Pad the beginning to length, using 0 by default.\n@Upper(text: string) → string — Uppercase text.\n@Lower(text: string) → string — Lowercase text.\n@Trim(text: string) → string — Trim surrounding whitespace.\n@Capitalize(text: string) → string — Uppercase the first letter of each whitespace-separated word.\n@Split(text: string, sep?: string) → string[] — Split, trim and discard empty strings. Default separator is comma.\n@Replace(text: string, find: string, replacement: string) → string — Replace every literal occurrence of find.\n@Duration(seconds: number, style?: \"short\" | \"clock\") → string — Duration as 1h 20m, 4m 05s, 45s, or a clock such as 1:20:00.\n@Default(value?: any, fallback: any) → any — Return fallback for null, empty string or nonfinite numbers; retain false and zero.\n@MixColor(from: string, to: string, t: number) → string — Interpolate two #rgb or #rrggbb colors at clamped fraction t.\n@Now() → string — Current time as an ISO timestamp.\n@Today() → string — Today's local calendar date as YYYY-MM-DD.\n@FormatDate(date: string | number, style?: \"date\" | \"short\" | \"long\" | \"weekday\" | \"month\" | \"time\" | \"datetime\" | \"iso\") → string — Format a local date, timestamp or ISO date-time.\n@AddDays(date: string | number, days: number) → string — Calendar date a number of days later (negative for earlier).\n@AddMonths(date: string | number, months: number) → string — Calendar date months later; constrain the day to the destination month's length.\n@DaysBetween(from: string | number, to: string | number) → number — Signed number of calendar days, independent of DST.\n@MonthsBetween(from: string | number, to: string | number) → number — Signed whole calendar months between dates.\n@StartOf(date: string | number, unit: \"week\" | \"month\" | \"year\") → string — First date of a Monday-based week, month or year.\n@GroupBy(rows: any[], key: string, field?: string, agg?: \"sum\" | \"avg\" | \"count\" | \"min\" | \"max\") → any[] — Aggregate per key in first-seen order; without field count records.\n@Pivot(rows: any[], rowKey: string, colKey: string, field?: string, agg?: \"sum\" | \"avg\" | \"count\" | \"min\" | \"max\") → any[] — One record per rowKey and one aggregate column per colKey.\n@Top(rows: any[], field: string, n: number, direction?: \"desc\" | \"asc\") → any[] — The n greatest field values, or smallest in asc order.\n@Between(rows: any[], field: string, min?: any, max?: any) → any[] — Inclusive range of field values, with null for an open end; supports YYYY-MM-DD text.\n@Bucket(rows: any[], dateField: string, unit: \"day\" | \"week\" | \"month\", field?: string, agg?: \"sum\" | \"avg\" | \"count\" | \"min\" | \"max\") → any[] — Chronological calendar buckets; fill missing periods with zero for sum/count.\n@Cumulative(rows: any[], field: string) → any[] — Replace a field with its running sum; empty field processes numbers directly.\n@MovingAvg(rows: any[], field: string, window: number) → any[] — Trailing moving average with a positive window; empty field processes numbers directly.\n@Change(current: number, previous: number) → number — Percent change from previous to current; null when previous is zero.\n@Histogram(values: number[], bins: number, min?: number, max?: number) → any[] — Counts in equal-width bins, including the maximum in the final bin.\n@Stats(values: number[]) → {count: number, min: number, max: number, mean: number, median: number, stdev: number} — Numeric summary with population standard deviation. All zeros for empty data.\n\nBuiltins compose — output of one is input to the next:\n`@Count(@Filter(data.rows, \"field\", \"==\", \"val\"))` for KPIs/chart values, `@Round(@Avg(data.rows.score), 1)`, `@Each(data.rows, \"item\", Comp(item.field))` for per-item rendering.\nArray pluck: `data.rows.field` extracts a field from every row → use with @Sum, @Avg, charts, tables.\n\nIMPORTANT @Each rule: The loop variable (e.g. \"item\") is ONLY available inside the @Each template expression. Always inline the template — do NOT extract it to a separate statement.\nCORRECT: `list = @Each(rows, \"t\", Comp(t.name))`\nWRONG: `item = Comp(t.name)` then `list = @Each(rows, \"t\", item)`, because t is undefined in item.\n\n## Action — Button Behavior\n\nAn action wires a button click to operations. Pass one @-prefixed step bare, e.g. Button(\"Ask\", @ToAssistant(\"Tell me more\")). Put several steps in Action([...]), e.g. Button(\"Read\", Action([@OpenUrl(\"https://example.com\"), @ToAssistant(\"Summarize this page\")])). Steps execute in order.\nButtons without an action automatically send their label to the assistant (equivalent to @ToAssistant(label)).\n\nAvailable steps:\n- @ToAssistant(message: string, context?: any) — Send a message to the assistant (for conversational buttons like \"Tell me more\", \"Explain this\"). The optional context is any value (object, array, string, number) passed to the assistant as hidden data, e.g. @ToAssistant(\"Show details\", {orderId: 42})\n- @OpenUrl(url: string) — Navigate to a URL\n- @Set(variable: $variable, value: any) — Set a $variable to a specific value\n- @Reset(variable: $variable) — Reset $variables to their declared defaults; pass several to reset each (e.g. @Reset($title, $priority) restores $title=\"\" and $priority=\"medium\")\n- @CopyToClipboard(text: string) — Copy text through the host clipboard bridge; action completion reflects the host response.\n\nExample — simple nav:\n```\nviewBtn = Button(\"View\", @OpenUrl(\"https://example.com\"))\n```\n\n- An action can be assigned to a variable or inlined: Button(\"Go\", onSubmit) and Button(\"Go\", Action([...])) both work\n\n## Hoisting & Streaming (CRITICAL)\n\nwhale-ui supports hoisting: a reference can be used BEFORE it is defined. The parser resolves all references after the full input is parsed.\n\nDuring streaming, the output is re-parsed on every chunk. Undefined references are temporarily unresolved and appear once their definitions stream in. This creates a progressive top-down reveal — structure first, then data fills in.\n\n**Recommended statement order for optimal streaming:**\n1. `root = Col(...)` — UI shell appears immediately\n2. $variable declarations — state ready for bindings\n3. Component definitions — fill in with data already available\n4. Data values — leaf content last\n\nAlways write the root = Col(...) statement first so the UI shell appears immediately, even before child data has streamed in.\n\n## Examples\n\nroot = Col([Title(\"Order estimate\",\"md\"), Text(\"Adjust the quantity to update your total.\",\"sm\",\"muted\"), Grid([Input($quantity,\"Quantity\",\"number\"),Input($price,\"Unit price\",\"number\")],2,240,4), Row([Col([Caption(\"Estimated total\"),Title(@Format(@Clamp(@Default($quantity,1),1,100)*@Clamp(@Default($price,12),0,10000),\"currency\",2,\"USD\"),\"2xl\")],1),Spacer(),Button(\"Reset\",@Reset($quantity,$price),\"outline\")],3)],5)\n$quantity = 1\n$price = 12\n\nroot = Col([Plot({series: [{expr: \"sin(x)\"}], xMin: -6, xMax: 6})])\n\n## Important Rules\n- Choose components that best represent the content (tables for comparisons, charts for trends, forms for input, etc.)\n\n## Final Verification\nBefore finishing, walk your output and verify:\n1. root = Col(...) is the FIRST line (for optimal streaming).\n2. Every referenced name is defined. Every defined name (other than root) is reachable from root.\n3. Every $binding appears in at least one component or expression.\n\n- Each statement occupies one line. Use positional component arguments. Define every referenced name and connect every defined value to root.\n- Mutable $variable defaults must be literal values. Use @Set and @Reset for local interactions. Guard empty numeric inputs with @Default and @Clamp.\n- Use real data from the conversation or tools. For a self-contained interactive page, deliver the Whale UI program directly through a fence or render_ui; do not inspect or modify the host application source to construct it. SearchImage and street routing are host resources; component action APIs do not grant arbitrary tool access.\n- Deliver a compact complete first version with short copy and useful local interactions; omit repeated prose summaries of values already on the page. Use drawings for geometry and mechanisms and charts for numerical comparisons. After render_ui reports success, the interface is already visible; do not render the same page a second time.\n- @Min and @Max each take ONE numeric array: @Min([a,b]), @Max([a,b]); never @Min(a,b). Build a few shared calculations and keep each section focused on the user's question.\n- Use a single concise md page title, 14px body text, 12px secondary text and one clear primary action. Do not add product names, demo labels, empty status bars or decorative badges.\n- All gap/padding arguments use 4px units, not pixels: 2 = 8px, 3 = 12px, 4 = 16px, 5 = 20px, 6 = 24px. Card(children, variant, 5, 3) has 20px padding and 12px gap. Never pass 16/20/24 for those pixel sizes. Prefer default Card padding. Use Grid minChildWidth 240–280 for inputs. Keep metrics together in one plain Row/Grid; do not create a card per number. Buttons keep natural width; Card groups related content and should not wrap the whole page or another card.\n- Use one statement per line and positional arguments. References may be defined after root. Defaults for mutable $variables are literals. String object keys may contain any language; quote keys for reliable interchange.\n- Action steps execute in order. Each step reads state at its execution time. @Set and @Reset stay local. Clipboard, links and conversation submission await the host result; failed steps stop the remaining sequence.\n- The viewer has no model API, filesystem, shell, credentials or arbitrary business-tool provider. Obtain real data with the conversation tools before creating the interface. Existing permissions still apply.\n- Incomplete or invalid final programs show diagnostics. Complete all references and components before ending the fence. Use the same field identity for the same user input and a different identity for different inputs.\n- Compose a finished Whale Isle interface for the user task. Show one concise content title (Title md), a short explanation only when needed, then the working content. Do not add product names, demo captions, implementation notes, empty status bars or redundant readiness badges.\n- Use the shared desktop typography and controls: body text md, secondary copy sm, section title sm, and md for the page title. Use 2xl or 3xl only for one meaningful numeric result, never for a sentence. Let default buttons keep their natural width; place one primary action and related outline/ghost actions together in a Row. Use block only when a deliberate full-width action is needed.\n- All gap and padding arguments are counts of 4px, not pixels. For 8/12/16/20/24px use 2/3/4/5/6. Card(children,\"soft\",5,3) means 20px padding and 12px gap; Card(...,16,...) would create 64px padding and is excessive. Prefer default Card padding. Use 5 or 6 between sections, 3 within groups, 2 between label and value. Group related inputs in Grid with minChildWidth 240–280 so a narrow conversation stacks fields. Keep metrics in one plain Grid/Row with only the main result enlarged. Avoid wide fixed rows, a card per metric, oversized controls, centered prose and dense walls of badges.\n- Use Card only for content that belongs together, not around the entire page or inside another card. Prefer plain sections, a restrained table or a chart with a small readable legend; do not stretch short cards to fill a tall neighbor. Use the existing semantic palette without custom CSS, decorative gradients or arbitrary font/colour overrides.\n\n## Specialized visual options\n\nPlot, Mermaid, Scene3D, EChart, Diagram, Blocks, Quiz, FileTree, Timeline, Steps, KeyValue, Diff, Json, Tabs and Accordion take an options object from the corresponding component below. Genui({items:[...]}) can combine these declarative components inside a normal Whale UI page. Local controls and field state use the same document owner. For quizzes and grouped forms, use stable ids/groups and submit to send their payload. Exported HTML keeps local controls; sending a message requires the conversation host.\n\narrow: {type?:string, span?:number, dir?:down|right, length?:number, label?:string}\naccordion: {type?:string, span?:number, items:array}\naudio: {type?:string, span?:number, src:string, alt?:string, loop?:boolean}\navatar: {type?:string, span?:number, name:string, color?:string}\nbadge: {type?:string, span?:number, label:string, tone?:success|warn|danger|accent, icon?:string}\nbreadcrumb: {type?:string, span?:number, items:array}\nbutton: {type?:string, span?:number, label:string, tone?:primary|danger|success|ghost, full?:boolean, small?:boolean, icon?:string, action?:string}\ncallout: {type?:string, span?:number, title?:string, content:string, tone?:info|success|warning|error}\ncard: {type?:string, span?:number, title?:string, eyebrow?:string, items:nodes, tone?:info|success|warning|danger, accent?:string, flat?:boolean}\nchart: {type?:string, span?:number, kind?:bars|line|donut, data?:array, series?:array, horizontal?:boolean, stacked?:boolean, filter?:string, palette?:array}\ncheckbox: {type?:string, span?:number, label:string, checked?:boolean, action?:string, group?:string}\ncode: {type?:string, span?:number, lang?:string, code:string}\ncol: {type?:string, span?:number, items:nodes, gap?:number, width?:number}\ncopy: {type?:string, span?:number, label?:string, text:string}\ndiagram: {type?:string, span?:number, kind:architecture|it-state|flowchart|sequence|state|er|timeline|swimlane|quadrant|radar|loop|nested|tree|org-chart|layers|venn|pyramid|bar|line|gantt|scatter|high-level|process|medallion|data-flow|dp-integration|dp-security-matrix, variant?:light|dark|editorial, title?:string, nodes:array, edges?:array, zones?:array, theme?:object}\ndiff: {type?:string, span?:number, diffs:array}\ndivider: {type?:string, span?:number, label?:string}\nechart: {type?:string, span?:number, title?:string, height?:number, preset?:bar|line|area|pie|scatter|radar|gauge|funnel|treemap|sankey|graph|heatmap|bigline|wordCloud, data?:array, series?:array, links?:array, palette?:array, option?:object}\nfile-tree: {type?:string, span?:number, items:array}\ngrid: {type?:string, span?:number, cols?:number, items:nodes}\nblocks: {type?:string, span?:number, rows:array, columns?:number, caption?:string, title?:string}\nicon: {type?:string, span?:number, name:string, label?:string, tone?:default|muted|info|success|warning|danger, size?:number, tile?:boolean}\nimage: {type?:string, span?:number, src:string, alt?:string, caption?:string}\ninput: {type?:string, span?:number, label?:string, placeholder?:string, value?:string, inputType?:text|email|password|color, action?:string, id?:string}\njson: {type?:string, span?:number, value:unknown}\nkeyvalue: {type?:string, span?:number, pairs:array}\nlink: {type?:string, span?:number, label:string, href?:string}\nlist: {type?:string, span?:number, items:array, filter?:string}\nmermaid: {type?:string, span?:number, code:string}\nsvg: {type?:string, span?:number, code:string, title?:string, height?:number}\nplot: {type?:string, span?:number, series:array, xMin?:number, xMax?:number, yMin?:number, yMax?:number, title?:string}\nprogress: {type?:string, span?:number, value:number, label?:string, valueLabel?:string, variant?:bar|ring, target?:number}\nquiz: {type?:string, span?:number, question:string, options:array, explanation?:string, id?:string, action?:string}\nradio: {type?:string, span?:number, label?:string, options:array, selected?:number, action?:string, group?:string, answer?:unknown, explanation?:string}\nrow: {type?:string, span?:number, items:nodes, wrap?:boolean, spacer?:boolean, justify?:start|center|end|between}\nscene3d: {type?:string, span?:number, title?:string, meshes:array, ambient?:number, background?:string}\nselect: {type?:string, span?:number, label?:string, options:array, action?:string, selected?:number, id?:string}\nslider: {type?:string, span?:number, label?:string, min?:number, max?:number, step?:number, value?:number, action?:string, id?:string}\nspacer: {type?:string, span?:number}\nhero: {type?:string, span?:number, title:string, subtitle?:string, value?:string, label?:string, delta?:string, spark?:array, tone?:accent|success|warning|danger}\nstat: {type?:string, span?:number, label:string, value:string, delta?:string, spark?:array, size?:hero}\nsteps: {type?:string, span?:number, steps:array, current?:number}\nsubmit: {type?:string, span?:number, label:string, action?:string, resetAction?:string, groups?:array}\nswitch: {type?:string, span?:number, label:string, checked?:boolean, action?:string}\ntable: {type?:string, span?:number, columns:array, rows:array, types?:array, total?:boolean, details?:array, filter?:string, filterColumn?:number, sortField?:string, export?:boolean}\ntabs: {type?:string, span?:number, tabs:array}\ntext: {type?:string, span?:number, content:string, size?:display|h1|h2|h3|body|muted|caption, center?:boolean, align?:left|center|right, tone?:danger|success|warning|info|muted, mono?:boolean}\ntextarea: {type?:string, span?:number, label?:string, placeholder?:string, rows?:number, value?:string, action?:string, id?:string}\ntimeline: {type?:string, span?:number, items:array}\nvideo: {type?:string, span?:number, src:string, alt?:string, poster?:string, loop?:boolean, muted?:boolean, aspectRatio?:16:9|4:3|1:1|9:16}\n\nUse only the whale-ui fence for new generated interfaces. Existing openui, openui-lang and dsh-ui history remains readable through the same runtime."
